Here is the Arduino sketch to light the LED on pin 13 while the button on pin 2 is held down, using the internal pull-up resistor.

MAKE CODE: ButtonHoldLED
language arduino
// Lights LED on pin 13 while button on pin 2 is held.
// Wiring: Button between pin 2 and GND.
// The internal pull-up keeps pin 2 HIGH when open, LOW when pressed.

const int buttonPin = 2;
const int ledPin = 13;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP); // Enable internal pull-up resistor
  pinMode(ledPin, OUTPUT);          // Set LED pin as output
}

void loop() {
  // Read the button state. 
  // Since it's a pull-up, reading LOW means the button is pressed.
  int buttonState = digitalRead(buttonPin);

  if (buttonState == LOW) {
    digitalWrite(ledPin, HIGH); // Turn LED ON
  } else {
    digitalWrite(ledPin, LOW);  // Turn LED OFF
  }
}
END

MAKE CODE: Servo Sweep
language arduino
// Sweep a hobby servo from 0 to 180 degrees and back.
// Wiring: servo signal (orange/white) to pin 9, red to 5V, brown/black to GND.
// A big servo needs its own 5-6 V supply (grounds joined), not the Uno's 5V.
#include <Servo.h>

Servo arm;
const int servoPin = 9;

void setup() {
  arm.attach(servoPin);
}

void loop() {
  for (int angle = 0; angle <= 180; angle += 2) {
    arm.write(angle);
    delay(15);
  }
  for (int angle = 180; angle >= 0; angle -= 2) {
    arm.write(angle);
    delay(15);
  }
}
END

Here is the P1AM-100 sketch for the tank pump logic. The pump starts when the low float switch (Input 1) is activated and stops when the high float switch (Input 2) is activated.

MAKE CODE: Tank Pump Control
language arduino
// P1AM-100: Tank pump control
// Slot 1: Discrete Input Module
//   Channel 1: Low Float Switch (NO) - Turns ON when water is low
//   Channel 2: High Float Switch (NO) - Turns ON when water is high
// Slot 2: Discrete Output Module
//   Channel 1: Pump Contactor

#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
const int lowFloatPin = 1;
const int highFloatPin = 2;
const int pumpPin = 1;

bool pumpRunning = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ; // Wait for modules to initialize
  }
}

void loop() {
  // Read inputs: NO switch is ON (true) when water level triggers it
  bool lowActive = P1.readDiscrete(inSlot, lowFloatPin);
  bool highActive = P1.readDiscrete(inSlot, highFloatPin);

  // Logic:
  // Start pump if low float is active (water is low)
  // Stop pump if high float is active (water is high)
  // If neither is active, keep the pump in its current state (latching)

  if (highActive) {
    pumpRunning = false;
  } else if (lowActive) {
    pumpRunning = true;
  }
  // If both are false, pumpRunning retains its previous value

  // Write output
  P1.writeDiscrete(pumpRunning, outSlot, pumpPin);
}
END

MAKE CODE: Sales CSV Max Amount
python
import csv
import sys

def main():
    if len(sys.argv) < 2:
        print("usage: python3 sales_max.py sales.csv")
        return

    filename = sys.argv[1]
    max_val = None

    try:
        with open(filename, newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                # Assuming the column is named 'amount'
                try:
                    val = float(row['amount'])
                    if max_val is None or val > max_val:
                        max_val = val
                except (KeyError, ValueError):
                    # Skip rows with missing or non-numeric 'amount'
                    continue

        if max_val is not None:
            print(f"{max_val}")
        else:
            print("No valid numeric values found in 'amount' column.")

    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
END

